// Fonction pour obtenir une traduction
export const getConfigApiText = (lang, path) => {
  const keys = path.split('.');
  let value = configApiTranslations[lang] || configApiTranslations.fr;
  
  for (const key of keys) {
    value = value?.[key];
    if (!value) return path;
  }
  
  return value;
};
